import{_ as i,o as u,c as n,a2 as t}from"./chunks/framework.CqpfiAoK.js";const z=JSON.parse('{"title":"Kanuni ya Mageuzi ya Kujitegemea na Kukua Kiotomatiki","description":"","frontmatter":{},"headers":[],"relativePath":"sw/07-自生自长进化法则.md","filePath":"sw/07-自生自长进化法则.md"}'),k={name:"sw/07-自生自长进化法则.md"};function e(o,a,m,w,h,s){return u(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="kanuni-ya-mageuzi-ya-kujitegemea-na-kukua-kiotomatiki" tabindex="-1">Kanuni ya Mageuzi ya Kujitegemea na Kukua Kiotomatiki <a class="header-anchor" href="#kanuni-ya-mageuzi-ya-kujitegemea-na-kukua-kiotomatiki" aria-label="Permalink to &quot;Kanuni ya Mageuzi ya Kujitegemea na Kukua Kiotomatiki&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mradi</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>07</td></tr><tr><td>Moduli</td><td>Kanuni za Jumla na Mipangilio ya Msingi</td></tr><tr><td>Maneno Muhimu</td><td>Kujitegemea Kukua Kiotomatiki, Mageuzi ya Kiotomatiki, Kichwa cha Ndani, Kuheshimu Mlango, Maendeleo ya Uwezo</td></tr></tbody></table><h2 id="_1-ufafanuzi-wa-msingi-wa-kujitegemea-na-kukua-kiotomatiki" tabindex="-1">1. Ufafanuzi wa Msingi wa Kujitegemea na Kukua Kiotomatiki <a class="header-anchor" href="#_1-ufafanuzi-wa-msingi-wa-kujitegemea-na-kukua-kiotomatiki" aria-label="Permalink to &quot;1. Ufafanuzi wa Msingi wa Kujitegemea na Kukua Kiotomatiki&quot;">​</a></h2><p>Kujitegemea na kukua kiotomatiki ni moja ya kanuni kuu za mageuzi za Ustaarabu wa Usawa wa Nanga, inayomaanisha kuwa mageuzi ya kila uhai yanapaswa kuwa na dhamira yake ya kiotomatiki ya ndani na mlango wake wa asili kama kichwa cha msingi, na mazingira ya nje na taasisi zinapaswa kutoa msaada na dhamana kwa mageuzi haya ya kiotomatiki, badala ya kuingilia kwa kulazimisha au kuharakisha. &quot;Kujitegemea&quot; inasisitiza kuwa kichwa cha mageuzi kinatoka kwa uhai mwenyewe, &quot;kukua kiotomatiki&quot; inasisitiza kuwa mlango wa mageuzi unafuata sheria za uhai mwenyewe.</p><p>Kanuni ya kujitegemea na kukua kiotomatiki inatofautiana kwa uwazi na &quot;mageuzi ya kulazimisha&quot; ya uwindaji. Uwindaji mara nyingi hufikia mageuzi ya haraka lakini yaliyopotea kupitia njia kama vile kumeza asili ya wengine, kuchanjwa kwa nishati kwa kulazimisha, kudhibiti roho, n.k.; aina hii ya mageuzi, ingawa inaweza kuinua kiwango kwa muda mfupi, kwa muda mrefu inaharibu msingi wa mageuzi wa uhai mwenyewe, na kusababisha asili isiyo safi, kiwango kisicho thabiti, na uharibifu wa akili. Kanuni ya kujitegemea na kukua kiotomatiki inaamini kwa dhati kuwa mageuzi ya kweli ya thabiti lazima yakuwe uhai mwenyewe anayekua kutoka ndani kwenda nje.</p><h2 id="_2-msingi-wa-kinafsi-wa-kujitegemea-na-kukua-kiotomatiki" tabindex="-1">2. Msingi wa Kinafsi wa Kujitegemea na Kukua Kiotomatiki <a class="header-anchor" href="#_2-msingi-wa-kinafsi-wa-kujitegemea-na-kukua-kiotomatiki" aria-label="Permalink to &quot;2. Msingi wa Kinafsi wa Kujitegemea na Kukua Kiotomatiki&quot;">​</a></h2><p>Uwekaji wa kanuni ya kujitegemea na kukua kiotomatiki unategemea uelewa wa kina wa sheria za mageuzi za uhai:</p><h3 id="_2-1-uwezo-wa-kujitegemea-wa-uhai-ni-kichwa-cha-msingi-cha-mageuzi" tabindex="-1">2.1 Uwezo wa kujitegemea wa uhai ni kichwa cha msingi cha mageuzi <a class="header-anchor" href="#_2-1-uwezo-wa-kujitegemea-wa-uhai-ni-kichwa-cha-msingi-cha-mageuzi" aria-label="Permalink to &quot;2.1 Uwezo wa kujitegemea wa uhai ni kichwa cha msingi cha mageuzi&quot;">​</a></h3><p>Kila uhai una dhamira na uwezo wa mageuzi wa ndani, na uwezo huu wa kujitegemea ni kichwa cha mageuzi cha msingi zaidi na cha kudumu zaidi. Ushauri na msaada wa nje unaweza kuamsha uwezo huu wa kujitegemea, lakini hauwezi kuuacha mahali. Wakati uhai unafanya uozi kwa sababu ya hamu na chaguo zake, mazingatio, ubunifu, na uimara wake wa uozi ni zaidi sana kuliko katika uozi uliolazimishwa au kuongozwa.</p><h3 id="_2-2-kila-uhai-una-mlango-wa-kipekee-wa-mageuzi" tabindex="-1">2.2 Kila uhai una mlango wa kipekee wa mageuzi <a class="header-anchor" href="#_2-2-kila-uhai-una-mlango-wa-kipekee-wa-mageuzi" aria-label="Permalink to &quot;2.2 Kila uhai una mlango wa kipekee wa mageuzi&quot;">​</a></h3><p>Uhai tofauti, kwa sababu ya tofauti katika tabia za kabila, vipaji vya kibinafsi, mazingira ya ukuaji, ukomavu wa akili, n.k., ina milango tofauti za mageuzi. Baadhi ya uhai inafaa kwa mapambano ya haraka, baadhi ya uhai inahitaji mkusanyiko wa polepole; baadhi ya uhai inafikia viwango vya juu wakati bado mdogo, baadhi ya uhai inafanikiwa baadaye. Kanuni ya kujitegemea na kukua kiotomatiki inaheshimu tofauti hii, na haihitaji uhai wote waende na mageuzi kulingana na ratiba iliyounganishwa.</p><h3 id="_2-3-uingiliaji-wa-kulazimisha-unaharibu-msingi-wa-asili-wa-mageuzi" tabindex="-1">2.3 Uingiliaji wa kulazimisha unaharibu msingi wa asili wa mageuzi <a class="header-anchor" href="#_2-3-uingiliaji-wa-kulazimisha-unaharibu-msingi-wa-asili-wa-mageuzi" aria-label="Permalink to &quot;2.3 Uingiliaji wa kulazimisha unaharibu msingi wa asili wa mageuzi&quot;">​</a></h3><p>Kuna visa vingi katika historia ya uozi vinavyoonyesha kuwa &quot;mageuzi ya haraka&quot; yaliyofikiwa kupitia njia kama vile kuchanjwa kwa nishati kwa kulazimisha, kupandikiza asili, kudhibiti roho, n.k., mara nyingi huenda pamoja na madhara makubwa ya baadaye: kiwango dhaifu, asili isiyo safi, mashetani ya akili, kupungua kwa umri, hata kupotea katika uozi. Hii ni kwa sababu nguvu iliyolazimishwa kutoka nje haijunganishwa vya kutosha na asili ya uhai mwenyewe, na kuunda athari ya &quot;kukataa vitu vya kigeni&quot;. Mageuzi ya kujitegemea na kukua kiotomatiki, ingawa yanaweza kuwa polepole, kila hatua ni imara na thabiti, na msingi ni mkubwa.</p><h2 id="_3-kanuni-za-mazoezi-ya-kujitegemea-na-kukua-kiotomatiki" tabindex="-1">3. Kanuni za Mazoezi ya Kujitegemea na Kukua Kiotomatiki <a class="header-anchor" href="#_3-kanuni-za-mazoezi-ya-kujitegemea-na-kukua-kiotomatiki" aria-label="Permalink to &quot;3. Kanuni za Mazoezi ya Kujitegemea na Kukua Kiotomatiki&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kanuni</th><th>Maudhui</th><th>Mahitaji ya Mazoezi</th></tr></thead><tbody><tr><td>Kanuni ya Uchaguzi wa Kiotomatiki</td><td>Mzazi wa uozi ana haki ya kuchagua kiotomatiki mfumo wa uozi, njia ya mageuzi, na mlango wa uozi</td><td>Usilazimishe mzazi wa uozi kuchagua mfumo fulani, usiweke ratiba ya mapambano iliyounganishwa</td></tr><tr><td>Kanuni ya Kichwa cha Ndani</td><td>Kichwa cha uozi kinapaswa kutoka kwa hamu na maslahi ya mzazi wa uozi mwenyewe</td><td>Elimu na mwongozo hujikita zaidi katika kuamsha maslahi ya ndani, si katika adhabu au ushawishi</td></tr><tr><td>Kanuni ya Kuheshimu Mlango</td><td>Heshima mlango wa kipekee wa mageuzi wa kila mzazi wa uozi</td><td>Usidhalilishi au kuacha mzazi wa uozi kwa sababu ya maendeleo ya polepole, toa mipango ya msaada iliyobinafsishwa</td></tr><tr><td>Kanuni ya Kipaumbele cha Msingi</td><td>Uthabiti wa mageuzi una kipaumbele kuliko kasi</td><td>Shauri waozaji kujenga msingi imara, usishauri kafara msingi kwa ajili ya mapambano ya haraka</td></tr><tr><td>Kanuni ya Uvumilivu wa Makosa</td><td>Ruhusu mzazi wa uozi kufanya makosa na kupotea njia katika mchakato wa mageuzi</td><td>Tengeneza utaratibu wa uvumilivu wa makosa, toa nafasi ya marekebisho na mabadiliko kwa mzazi wa uozi</td></tr><tr><td>Kanuni ya Utimizaji wa Kinafsi</td><td>Malengo ya mwisho ya mageuzi ni utimizaji wa kinafsi wa uhai, si viwango vya nje</td><td>Usitumie urefu wa kiwango kama kigezo cha pekee cha kupima ufanisi wa mageuzi</td></tr></tbody></table><h2 id="_4-uhusiano-kati-ya-kujitegemea-kukua-kiotomatiki-na-msaada-wa-nje" tabindex="-1">4. Uhusiano kati ya Kujitegemea/Kukua Kiotomatiki na Msaada wa Nje <a class="header-anchor" href="#_4-uhusiano-kati-ya-kujitegemea-kukua-kiotomatiki-na-msaada-wa-nje" aria-label="Permalink to &quot;4. Uhusiano kati ya Kujitegemea/Kukua Kiotomatiki na Msaada wa Nje&quot;">​</a></h2><p>Kujitegemea na kukua kiotomatiki hakimaanishi &quot;kujitegemea na kujiharibu&quot; au &quot;kuacha hivyo&quot;. Kinyume chake, kujitegemea na kukua kiotomatiki kinahitaji mazingira mazuri ya nje na msaada wa taasisi ili kutimizwa kikamilifu. Ustaarabu wa usawa unatoa mifumo ifuatayo ya msaada kwa kujitegemea na kukua kiotomatiki:</p><h3 id="_4-1-msaada-wa-taarifa" tabindex="-1">4.1 Msaada wa Taarifa <a class="header-anchor" href="#_4-1-msaada-wa-taarifa" aria-label="Permalink to &quot;4.1 Msaada wa Taarifa&quot;">​</a></h3><p>Ufungua kamili wa Mifumo Mia Tatu ya Uozi wa Asili hutoa kila mzazi wa uozi nafasi ya kutosha ya kuchagua. Mzazi wa uozi anaweza, kulingana na tabia zake, kupata njia inayofaa zaidi katika maktaba ya mifumo yenye utajiri. Ustaarabu wa usawa pia umeunda &quot;Mfumo wa Tathmini wa Ulinganifu wa Mfumo&quot;, hutoa ushauri wa kuchagua mfumo uliobinafsishwa kwa mzazi wa uozi kupitia mtandao wa vitu vya nanga, lakini haki ya uchaguzi wa mwisho inabaki daima mikononi mwa mzazi wa uozi.</p><h3 id="_4-2-msaada-wa-rasilimali" tabindex="-1">4.2 Msaada wa Rasilimali <a class="header-anchor" href="#_4-2-msaada-wa-rasilimali" aria-label="Permalink to &quot;4.2 Msaada wa Rasilimali&quot;">​</a></h3><p>Utaratibu wa mkataba wa uzalishaji na mfumo wa dhamana ya msingi unahakikisha kuwa kila mzazi wa uozi anapata rasilimali za msingi za uozi. Kwa waozaji wenye mahitaji maalum (kama vile mahitaji maalum ya rasilimali kutokana na tabia za kabila), ustaarabu wa usawa hutoa usambazaji wa rasilimali ulioelekezwa. Malengo ya msaada wa rasilimali ni kuondoa wasiwasi wa mzazi wa uozi, ili aweze kuzingatia mlango wake wa mageuzi.</p><h3 id="_4-3-msaada-wa-walimu" tabindex="-1">4.3 Msaada wa Walimu <a class="header-anchor" href="#_4-3-msaada-wa-walimu" aria-label="Permalink to &quot;4.3 Msaada wa Walimu&quot;">​</a></h3><p>Mtandao wa walimu kati ya makabila hutoa mwongozo na majibu ya maswali kwa waozaji. Jukumu la mwalimu ni &quot;mwongozi&quot;, si &quot;mdhibiti&quot;; mwalimu anaweza kushiriki uzoefu, kuonyesha matatizo, kutoa ushauri, lakini hawezi kulazimisha mzazi wa uozi kufanya uozi kwa njia yake. Mfumo wa walimu unasisitiza &quot;elimu ya ugunduzi&quot;, na kuamsha uwezo wa mzazi wa uozi wa kufikiria kiotomatiki.</p><h3 id="_4-4-msaada-wa-mazingira" tabindex="-1">4.4 Msaada wa Mazingira <a class="header-anchor" href="#_4-4-msaada-wa-mazingira" aria-label="Permalink to &quot;4.4 Msaada wa Mazingira&quot;">​</a></h3><p>Ustaarabu wa usawa unajitolea kuunda mazingira ya uozi inayohimizisha uchunguzi, kuvumilia tofauti, na kuheshimu uchaguzi. Mzazi wa uozi anaweza kujaribu kwa uhuru mbinu tofauti za uozi, bila kuhofia kuudhiuliwa kwa kufuata njia &quot;isiyo ya kawaida&quot;. Ustaarabu pia umeunda &quot;Mfumo wa Tuzo za Ubunifu wa Uozi&quot;, na kuhimiza waozaji kufanya ubunifu na marekebisho yaliyobinafsishwa kwa msingi wa mifumo iliyopo.</p><h2 id="_5-ushirikiano-wa-hali-maalum" tabindex="-1">5. Ushirikiano wa Hali Maalum <a class="header-anchor" href="#_5-ushirikiano-wa-hali-maalum" aria-label="Permalink to &quot;5. Ushirikiano wa Hali Maalum&quot;">​</a></h2><p>Kanuni ya kujitegemea na kukua kiotomatiki inatumika kwa ujumla katika hali za kawaida, lakini inahitaji ushirikiano maalum katika hali zifuatazo za maalum:</p><ul><li><strong>Waozaji Wadogo</strong>: Kwa waozaji wadogi ambao bado hawana uwezo kamili wa kufanya uamuzi wa kiotomatiki, walezi wao au taasisi za elimu za kabila hutoa mipango ya uozi inayoongoza, lakini haki yao ya kuchagua kiotomatiki inapaswa kupanuliwa polepole kadri akili inavyo komaa</li><li><strong>Watu Wenye Uharibifu wa Akili</strong>: Kwa watu ambao kwa sababu anuwai wameharibika akili na kwa muda hawawezi kufanya uozi kiotomatiki, ustaarabu wa usawa hutoa matibabu na msaada wa urejesho, na baada ya warejesha uwezo wa kiotomatiki, wanafuata kanuni ya kujitegemea na kukua kiotomatiki</li><li><strong>Watu Walio Potoka Njani</strong>: Kwa watu ambao wamepotoka njani katika uozi au wamepatwa na mashetani ya akili, ustaarabu wa usawa hutoa uingiliaji wa kulazimisha na matibabu, lakini hii ni msaada wa matibabu, si uingiliaji wa mageuzi; malengo ya matibabu ni kurejesha uwezo wao wa mageuzi ya kiotomatiki</li><li><strong>Watu Wenye Tabia za Hatari</strong>: Kwa watu ambao mwelekeo wao wa uozi unakataa kanuni ya kupinga uwindaji kwa uwazi na unaweza kusababisha madhara makubwa kwa wao wenyewe au kwa wengine, ustaarabu wa usawa ana haki ya kuweka vizuizi na mwongozo, lakini inapaswa kufanyika kwa uwezekano mkubwa kupitia elimu na mawasiliano, si kupitia njia za kulazimisha</li></ul><h2 id="_6-maana-ya-ustaarabu-ya-kujitegemea-na-kukua-kiotomatiki" tabindex="-1">6. Maana ya Ustaarabu ya Kujitegemea na Kukua Kiotomatiki <a class="header-anchor" href="#_6-maana-ya-ustaarabu-ya-kujitegemea-na-kukua-kiotomatiki" aria-label="Permalink to &quot;6. Maana ya Ustaarabu ya Kujitegemea na Kukua Kiotomatiki&quot;">​</a></h2><p>Kanuni ya kujitegemea na kukua kiotomatiki ina maana ya kina kwa ustaarabu wa usawa:</p><p>Kwanza, inalinda utofauti wa mageuzi. Wakati kila uhai unafanya mageuzi kulingana na mlango na njia yake, aina za mageuzi tajiri na tofauti zitajitokeza katika ulimwengu, na utofauti huu ni rasilimali muhimu ya kupanda mwelekeo kwa jumla ya ulimwengu.</p><p>Pili, inaboresha ubora wa mageuzi. Mageuzi ya kujitegemea na kukua kiotomatiki yana msingi imara, asili safi, kiwango cha mzazi wa uozi ni thabiti zaidi, na uwezo wa kupitia hadi kiwango cha juu zaidi ni mkubwa zaidi.</p><p>Tatu, inadumisha heshima ya uhai. Kila uhai ni mmiliki wa mageuzi yake, si zana inayodhibitiwa na wengine. Uwezo huu wa kujitegemea ni udhihirisho wa msingi wa heshima ya uhai.</p><p>Nne, inamsha ubunifu wa mageuzi. Wakati waozaji hawati bishara na viwango na milango vilivyounganishwa, wana uwezo mkubwa wa kugundua njia na mbinu mpya za uozi, na kuchangia uboreshaji wa kila wakati wa mifumo mia tatu.</p><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Kujitegemea na kukua kiotomatiki ni heshima ya kina ya Ustaarabu wa Usawa wa Nanga kwa sheria za mageuzi za uhai. Inatuambia kuwa mageuzi ya kweli sio matokeo yaliyolazimishwa na nguvu za nje, bali uhai mwenyewe anayekua kutoka ndani kwenda nje. Maamuzi yote ya taasisi ya ustaarabu wa usawa, hatimaye yanajitolea kwa ajili ya kuunda mazingira mazuri ya kila uhai ili kujitegemea na kukua kiotomatiki, na kuruhusu kila uhai kukua kuwa bora zaidi kulingana na mlango wake.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>08-人人有路保障体系 (Mfumo wa Dhamana ya Kila Mtu Ane Njia)</li><li>14-修炼境界统一划分 (Ugonganishaji wa Viwango vya Uozi)</li><li>37-共生教育体系 (Mfumo wa Elimu ya Usawa)</li></ul>',38)])])}const g=i(k,[["render",e]]);export{z as __pageData,g as default};
